// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;
    function setUp() public { c = new airdrop(); }

    // fuzz the caller address and the uint value; we MUST pass an empty array to observe the difference
    function testFuzz_property(address caller, uint256 v) public {
        // keep caller non-zero to be an admissible actor
        vm.assume(caller != address(0));

        address[] memory tos = new address[](0); // the deciding input: empty recipients array

        // The reference contract requires _tos.length > 0 and therefore always reverts for empty arrays.
        // The mutant removes the require and will return true. We observe this by catching revert vs success.
        bool ok;
        // call as the fuzzed caller
        vm.prank(caller);
        try c.transfer(caller, address(0xdead), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // ASSERTION: For all inputs with an empty _tos, the correct contract should revert (ok == false).
        // The mutant that removed the require will make ok == true for some inputs (indeed for these),
        // causing this assertion to fail on the buggy version.
        assertTrue(ok == false);
    }
}
